247	  private static byte @Nullable [] textToNumericFormatV4(String ipString) {
248	    if (IPV4_DELIMITER_MATCHER.countIn(ipString) + 1 != IPV4_PART_COUNT) {
249	      return null; // Wrong number of parts
250	    }
251	
252	    byte[] bytes = new byte[IPV4_PART_COUNT];
253	    int start = 0;
254	    // Iterate through the parts of the ip string.
255	    // Invariant: start is always the beginning of an octet.
256	    for (int i = 0; i < IPV4_PART_COUNT; i++) {
257	      int end = ipString.indexOf(IPV4_DELIMITER, start);
258	      if (end == -1) {
259	        end = ipString.length();
260	      }
261	      try {
262	        bytes[i] = parseOctet(ipString, start, end);
263	      } catch (NumberFormatException ex) {
264	        return null;
265	      }
266	      start = end + 1;
267	    }
268	
