81	   *
82	   * <p>This method will detect any non-empty cycle, including self-loops (a cycle of length 1).
83	   */
84	  public static boolean hasCycle(Network<?, ?> network) {
85	    // In a directed graph, parallel edges cannot introduce a cycle in an acyclic graph.
86	    // However, in an undirected graph, any parallel edge induces a cycle in the graph.
87	    if (!network.isDirected()
88	        && network.allowsParallelEdges()
89	        && network.edges().size() > network.asGraph().edges().size()) {
90	      return true;
91	    }
92	    return hasCycle(network.asGraph());
93	  }
