97	   * we've already visited (following only outgoing edges and without reusing edges), we know
98	   * there's a cycle in the graph.
99	   */
100	  private static <N> boolean subgraphHasCycle(
101	      Graph<N> graph, Map<Object, NodeVisitState> visitedNodes, N startNode) {
102	    Deque<NodeAndRemainingSuccessors<N>> stack = new ArrayDeque<>();
103	    stack.addLast(new NodeAndRemainingSuccessors<>(startNode));
104	
105	    while (!stack.isEmpty()) {
106	      // To peek at the top two items, we need to temporarily remove one.
107	      NodeAndRemainingSuccessors<N> top = stack.removeLast();
108	      NodeAndRemainingSuccessors<N> prev = stack.peekLast();
109	      stack.addLast(top);
110	
111	      N node = top.node;
112	      N previousNode = prev == null ? null : prev.node;
113	      if (top.remainingSuccessors == null) {
114	        NodeVisitState state = visitedNodes.get(node);
115	        if (state == NodeVisitState.COMPLETE) {
116	          stack.removeLast();
117	          continue;
118	        }
119	        if (state == NodeVisitState.PENDING) {
120	          return true;
121	        }
122	
123	        visitedNodes.put(node, NodeVisitState.PENDING);
124	        top.remainingSuccessors = new ArrayDeque<>(graph.successors(node));
125	      }
126	
127	      if (!top.remainingSuccessors.isEmpty()) {
128	        N nextNode = top.remainingSuccessors.remove();
129	        if (canTraverseWithoutReusingEdge(graph, nextNode, previousNode)) {
130	          stack.addLast(new NodeAndRemainingSuccessors<>(nextNode));
131	          continue;
132	        }
133	      }
134	
135	      stack.removeLast();
136	      visitedNodes.put(node, NodeVisitState.COMPLETE);
137	    }
138	    return false;
139	  }
