141	  private static final class NodeAndRemainingSuccessors<N> {
142	    final N node;
143	
144	    /**
145	     * The successors left to be visited, or {@code null} if we just added this {@code
146	     * NodeAndRemainingSuccessors} instance to the stack. In the latter case, we'll compute the
147	     * successors if we determine that we need them after we've performed the initial processing of
148	     * the node.
149	     */
150	    @Nullable Queue<N> remainingSuccessors;
151	
152	    NodeAndRemainingSuccessors(N node) {
153	      this.node = node;
154	    }
155	  }
