157	  /**
158	   * Determines whether an edge has already been used during traversal. In the directed case a cycle
159	   * is always detected before reusing an edge, so no special logic is required. In the undirected
160	   * case, we must take care not to "backtrack" over an edge (i.e. going from A to B and then going
161	   * from B to A).
162	   */
163	  private static boolean canTraverseWithoutReusingEdge(
164	      Graph<?> graph, Object nextNode, @Nullable Object previousNode) {
165	    if (graph.isDirected() || !Objects.equals(previousNode, nextNode)) {
166	      return true;
167	    }
168	    // This falls into the undirected A->B->A case. The Graph interface does not support parallel
169	    // edges, so this traversal would require reusing the undirected AB edge.
170	    return false;
171	  }
