173	  /**
174	   * Returns the transitive closure of {@code graph}. The transitive closure of a graph {@code G} is
175	   * a graph {@code T} that is a supergraph of {@code G}, augmented by, for each pair of nodes A and
176	   * B, an edge connecting node A to node B if there is a sequence of edges in {@code G} starting at
177	   * A and ending at B.
178	   *
179	   * <p>{@code strategy} defines the circumstances under which self-loops will be added to the
180	   * transitive closure graph.
181	   *
182	   * <p>This is a "snapshot" based on the current topology of {@code graph}, rather than a live view
183	   * of the transitive closure of {@code graph}. In other words, the returned {@link Graph} will not
184	   * be updated after modifications to {@code graph}.
185	   *
186	   * @since 33.6.0
187	   */
188	  // TODO(b/31438252): Consider optimizing for undirected graphs.
189	  public static <N> ImmutableGraph<N> transitiveClosure(
190	      Graph<N> graph, TransitiveClosureSelfLoopStrategy strategy) {
191	    ImmutableGraph.Builder<N> transitiveClosure =
192	        GraphBuilder.from(graph).allowsSelfLoops(true).immutable();
193	
194	    for (N node : graph.nodes()) {
195	      // add each node explicitly to include isolated nodes
196	      transitiveClosure.addNode(node);
197	      for (N reachableNode : getReachableNodes(graph, node, strategy)) {
198	        transitiveClosure.putEdge(node, reachableNode);
199	      }
200	    }
201	    return transitiveClosure.build();
202	  }
