204	  /**
205	   * Equivalent to {@code transitiveClosure(graph, ADD_SELF_LOOPS_ALWAYS)}. Callers should look at
206	   * the different strategy options that the new method supports rather than simply migrating to the
207	   * new method with the existing behavior; we believe that most callers will want to use the {@code
208	   * ADD_SELF_LOOPS_FOR_CYCLES} strategy.
209	   *
210	   * @since 33.1.0 (present with return type {@code Graph} since 20.0)
211	   * @deprecated Use {@link #transitiveClosure(Graph, TransitiveClosureSelfLoopStrategy)} instead.
212	   */
213	  @SuppressWarnings("InlineMeSuggester") // We expect most users to want to change behavior.
214	  @Deprecated
215	  public static <N> ImmutableGraph<N> transitiveClosure(Graph<N> graph) {
216	    return transitiveClosure(graph, ADD_SELF_LOOPS_ALWAYS);
