219	  /**
220	   * Returns the nodes reachable from {@code node} in {@code graph}, according to the given {@code
221	   * strategy}.
222	   */
223	  private static <N> Iterable<N> getReachableNodes(
224	      Graph<N> graph, N node, TransitiveClosureSelfLoopStrategy strategy) {
225	    Traverser<N> traverser = Traverser.forGraph(graph);
226	    switch (strategy) {
227	      case ADD_SELF_LOOPS_ALWAYS: // always include 'node'
228	        return traverser.breadthFirst(node);
229	      case ADD_SELF_LOOPS_FOR_CYCLES: // include 'node' iff there's an incident cycle
230	        // note that if 'node' has a self-loop, it will appear in its successors
231	        return traverser.breadthFirst(graph.successors(node));
232	    }
233	    throw new IllegalArgumentException("Unrecognized strategy: " + strategy);
234	  }
