236	  /**
237	   * A strategy for adding self-loops to {@linkplain #transitiveClosure(Graph,
238	   * TransitiveClosureSelfLoopStrategy) the transitive closure graph}. All strategies preserve
239	   * self-loops that are present in the original graph.
240	   *
241	   * <p>The strategies differ based on how they define "cycle incident to a node".
242	   *
243	   * @since 33.6.0
244	   */
245	  public enum TransitiveClosureSelfLoopStrategy {
246	    /**
247	     * Add a self-loop to each node in the original graph; this is based on a definition of "cycle
248	     * incident to a node" that includes zero-length cycles. This matches the behavior of the
249	     * now-deprecated {@link #transitiveClosure(Graph)} method.
250	     */
251	    ADD_SELF_LOOPS_ALWAYS,
252	    /**
253	     * Add a self-loop to each node that is incident to a cycle of length one or greater in the
254	     * original graph.
255	     */
256	    ADD_SELF_LOOPS_FOR_CYCLES
257	  }
