259	  /**
260	   * Returns the set of nodes that are reachable from {@code node}. Specifically, it returns all
261	   * nodes {@code v} such that there exists a path (a sequence of adjacent outgoing edges) starting
262	   * at {@code node} and ending at {@code v}. This implementation includes {@code node} as the first
263	   * element in the result.
264	   *
265	   * <p>If needed, the {@link Traverser} class provides more flexible and lighter-weight ways to
266	   * list the nodes reachable from a given node or nodes. See the <a
267	   * href="https://github.com/google/guava/wiki/GraphsExplained#Graph-traversal">"Graph traversal"
268	   * section of the Guava User's Guide</a> for more information.
269	   *
270	   * <p>The {@link Set} returned is a "snapshot" based on the current topology of {@code graph},
271	   * rather than a live view. In other words, modifications to {@code graph} made after this method
272	   * returns will not be reflected in the set.
273	   *
274	   * @throws IllegalArgumentException if {@code node} is not present in {@code graph}
275	   * @since 33.1.0 (present with return type {@code Set} since 20.0)
276	   */
277	  public static <N> ImmutableSet<N> reachableNodes(Graph<N> graph, N node) {
278	    checkArgument(graph.nodes().contains(node), NODE_NOT_IN_GRAPH, node);
279	    return ImmutableSet.copyOf(Traverser.forGraph(graph).breadthFirst(node));
280	  }
