286	  /**
287	   * Returns a view of {@code graph} with the direction (if any) of every edge reversed. All other
288	   * properties remain intact, and further updates to {@code graph} will be reflected in the view.
289	   */
290	  public static <N> Graph<N> transpose(Graph<N> graph) {
291	    if (!graph.isDirected()) {
