554	  /**
555	   * Returns the subgraph of {@code graph} induced by {@code nodes}. This subgraph is a new graph
556	   * that contains all of the nodes in {@code nodes}, and all of the {@link Graph#edges() edges}
557	   * from {@code graph} for which both nodes are contained by {@code nodes}.
558	   *
559	   * @throws IllegalArgumentException if any element in {@code nodes} is not a node in the graph
560	   */
561	  public static <N> MutableGraph<N> inducedSubgraph(Graph<N> graph, Iterable<? extends N> nodes) {
562	    MutableGraph<N> subgraph =
563	        (nodes instanceof Collection)
564	            ? GraphBuilder.from(graph).expectedNodeCount(((Collection) nodes).size()).build()
565	            : GraphBuilder.from(graph).build();
566	    for (N node : nodes) {
567	      subgraph.addNode(node);
568	    }
569	    for (N node : subgraph.nodes()) {
570	      for (N successorNode : graph.successors(node)) {
571	        if (subgraph.nodes().contains(successorNode)) {
572	          subgraph.putEdge(node, successorNode);
573	        }
574	      }
575	    }
576	    return subgraph;
577	  }
