595	    }
596	    for (N node : subgraph.nodes()) {
597	      for (N successorNode : graph.successors(node)) {
598	        if (subgraph.nodes().contains(successorNode)) {
599	          // requireNonNull is safe because the endpoint pair comes from the graph.
600	          subgraph.putEdgeValue(
601	              node,
