611	   * Returns the subgraph of {@code network} induced by {@code nodes}. This subgraph is a new graph
612	   * that contains all of the nodes in {@code nodes}, and all of the {@link Network#edges() edges}
613	   * from {@code network} for which the {@link Network#incidentNodes(Object) incident nodes} are
614	   * both contained by {@code nodes}.
615	   *
616	   * @throws IllegalArgumentException if any element in {@code nodes} is not a node in the graph
617	   */
618	  public static <N, E> MutableNetwork<N, E> inducedSubgraph(
619	      Network<N, E> network, Iterable<? extends N> nodes) {
620	    MutableNetwork<N, E> subgraph =
621	        (nodes instanceof Collection)
622	            ? NetworkBuilder.from(network).expectedNodeCount(((Collection) nodes).size()).build()
623	            : NetworkBuilder.from(network).build();
624	    for (N node : nodes) {
625	      subgraph.addNode(node);
626	    }
627	    for (N node : subgraph.nodes()) {
628	      for (E edge : network.outEdges(node)) {
629	        N successorNode = network.incidentNodes(edge).adjacentNode(node);
630	        if (subgraph.nodes().contains(successorNode)) {
631	          subgraph.addEdge(node, successorNode, edge);
632	        }
633	      }
634	    }
635	    return subgraph;
636	  }
