17	package com.google.common.graph;
18	
19	import org.jspecify.annotations.Nullable;
20	
21	/**
22	 * This class provides a skeletal implementation of {@link Graph}. It is recommended to extend this
23	 * class rather than implement {@link Graph} directly.
24	 *
25	 * @author James Sexton
26	 * @param <N> Node parameter type
27	 * @since 20.0
28	 */
29	public abstract class AbstractGraph<N> extends AbstractBaseGraph<N> implements Graph<N> {
30	  /** Constructor for use by subclasses. */
31	  public AbstractGraph() {}
32	
33	  @Override
34	  public final boolean equals(@Nullable Object obj) {
35	    if (obj == this) {
36	      return true;
37	    }
38	    if (!(obj instanceof Graph)) {
39	      return false;
40	    }
41	    Graph<?> other = (Graph<?>) obj;
42	
43	    return isDirected() == other.isDirected()
44	        && nodes().equals(other.nodes())
45	        && edges().equals(other.edges());
46	  }
47	
48	  @Override
49	  public final int hashCode() {
50	    return edges().hashCode();
51	  }
52	
53	  /** Returns a string representation of this graph. */
54	  @Override
55	  public String toString() {
56	    return "isDirected: "
57	        + isDirected()
58	        + ", allowsSelfLoops: "
59	        + allowsSelfLoops()
60	        + ", nodes: "
61	        + nodes()
62	        + ", edges: "
63	        + edges();
64	  }
65	}
