54	@GwtCompatible
55	public abstract class ImmutableTable<R, C, V> extends AbstractTable<R, C, V>
56	    implements Serializable {
57	
58	  /**
59	   * Returns a {@code Collector} that accumulates elements into an {@code ImmutableTable}. Each
60	   * input element is mapped to one cell in the returned table, with the rows, columns, and values
61	   * generated by applying the specified functions.
