38	/**
39	 * Implementation of {@code Multimap} whose keys and values are ordered by their natural ordering or
40	 * by supplied comparators. In all cases, this implementation uses {@link Comparable#compareTo} or
41	 * {@link Comparator#compare} instead of {@link Object#equals} to determine equivalence of
42	 * instances.
43	 *
44	 * <p><b>Warning:</b> The comparators or comparables used must be <i>consistent with equals</i> as
45	 * explained by the {@link Comparable} class specification. Otherwise, the resulting multiset will
46	 * violate the general contract of {@link SetMultimap}, which is specified in terms of {@link
47	 * Object#equals}.
48	 *
49	 * <p>The collections returned by {@code keySet} and {@code asMap} iterate through the keys
50	 * according to the key comparator ordering or the natural ordering of the keys. Similarly, {@code
51	 * get}, {@code removeAll}, and {@code replaceValues} return collections that iterate through the
52	 * values according to the value comparator ordering or the natural ordering of the values. The
53	 * collections generated by {@code entries}, {@code keys}, and {@code values} iterate across the
54	 * keys according to the above key ordering, and for each key they iterate across the values
55	 * according to the value ordering.
56	 *
57	 * <p>The multimap does not store duplicate key-value pairs. Adding a new key-value pair equal to an
58	 * existing key-value pair has no effect.
59	 *
60	 * <p>Null keys and values are permitted (provided, of course, that the respective comparators
61	 * support them). All optional multimap methods are supported, and all returned views are
62	 * modifiable.
63	 *
64	 * <p>This class is not threadsafe when any concurrent operations update the multimap. Concurrent
65	 * read operations will work correctly. To allow concurrent update operations, wrap your multimap
66	 * with a call to {@link Multimaps#synchronizedSortedSetMultimap}.
67	 *
68	 * <p>See the Guava User Guide article on <a href=
69	 * "https://github.com/google/guava/wiki/NewCollectionTypesExplained#multimap">{@code Multimap}</a>.
70	 *
71	 * @author Jared Levy
72	 * @author Louis Wasserman
73	 * @since 2.0
74	 */
75	@GwtCompatible
76	public final class TreeMultimap<K extends @Nullable Object, V extends @Nullable Object>
77	    extends AbstractSortedKeySortedSetMultimap<K, V> {
78	  private transient Comparator<? super K> keyComparator;
79	  private transient Comparator<? super V> valueComparator;
80	
81	  /**
82	   * Creates an empty {@code TreeMultimap} ordered by the natural ordering of its keys and values.
83	   */
84	  @SuppressWarnings("rawtypes") // https://github.com/google/guava/issues/989
85	  public static <K extends Comparable, V extends Comparable> TreeMultimap<K, V> create() {
86	    return new TreeMultimap<>(Ordering.natural(), Ordering.natural());
87	  }
88	
89	  /**
90	   * Creates an empty {@code TreeMultimap} instance using explicit comparators. Neither comparator
91	   * may be null; use {@link Ordering#natural()} to specify natural order.
92	   *
93	   * @param keyComparator the comparator that determines the key ordering
94	   * @param valueComparator the comparator that determines the value ordering
95	   */
