199	  /** Returns {@code null} if unable to parse into a {@code byte[]}. */
200	  private static byte @Nullable [] ipStringToBytes(String ipStringParam, @Nullable Scope scope) {
201	    String ipString = ipStringParam;
202	    // Make a first pass to categorize the characters in this string.
203	    boolean hasColon = false;
204	    boolean hasDot = false;
205	    int percentIndex = -1;
206	    for (int i = 0; i < ipString.length(); i++) {
207	      char c = ipString.charAt(i);
208	      if (c == '.') {
209	        hasDot = true;
210	      } else if (c == ':') {
211	        if (hasDot) {
212	          return null; // Colons must not appear after dots.
213	        }
214	        hasColon = true;
215	      } else if (c == '%') {
216	        percentIndex = i;
217	        break;
218	      } else if (Character.digit(c, 16) == -1) {
219	        return null; // Everything else must be a decimal or hex digit.
220	      }
221	    }
222	
223	    // Now decide which address family to parse.
224	    if (hasColon) {
225	      if (hasDot) {
226	        ipString = convertDottedQuadToHex(ipString);
227	        if (ipString == null) {
228	          return null;
229	        }
230	      }
231	      if (percentIndex != -1) {
232	        if (scope != null) {
233	          scope.scope = ipString.substring(percentIndex + 1);
234	        }
235	        ipString = ipString.substring(0, percentIndex);
236	      }
237	      return textToNumericFormatV6(ipString);
238	    } else if (hasDot) {
239	      if (percentIndex != -1) {
240	        return null; // Scope IDs are not supported for IPV4
241	      }
242	      return textToNumericFormatV4(ipString);
243	    }
244	    return null;
245	  }
