272	  private static byte @Nullable [] textToNumericFormatV6(String ipString) {
273	    // An address can have [2..8] colons.
274	    int delimiterCount = IPV6_DELIMITER_MATCHER.countIn(ipString);
275	    if (delimiterCount < 2 || delimiterCount > IPV6_PART_COUNT) {
276	      return null;
277	    }
278	    int partsSkipped = IPV6_PART_COUNT - (delimiterCount + 1); // estimate; may be modified later
279	    boolean hasSkip = false;
280	    // Scan for the appearance of ::, to mark a skip-format IPV6 string and adjust the partsSkipped
281	    // estimate.
282	    for (int i = 0; i < ipString.length() - 1; i++) {
283	      if (ipString.charAt(i) == IPV6_DELIMITER && ipString.charAt(i + 1) == IPV6_DELIMITER) {
284	        if (hasSkip) {
285	          return null; // Can't have more than one ::
286	        }
287	        hasSkip = true;
288	        partsSkipped++; // :: means we skipped an extra part in between the two delimiters.
289	        if (i == 0) {
290	          partsSkipped++; // Begins with ::, so we skipped the part preceding the first :
291	        }
292	        if (i == ipString.length() - 2) {
293	          partsSkipped++; // Ends with ::, so we skipped the part after the last :
294	        }
295	      }
296	    }
297	    if (ipString.charAt(0) == IPV6_DELIMITER && ipString.charAt(1) != IPV6_DELIMITER) {
298	      return null; // ^: requires ^::
299	    }
300	    if (ipString.charAt(ipString.length() - 1) == IPV6_DELIMITER
301	        && ipString.charAt(ipString.length() - 2) != IPV6_DELIMITER) {
302	      return null; // :$ requires ::$
303	    }
304	    if (hasSkip && partsSkipped <= 0) {
305	      return null; // :: must expand to at least one '0'
306	    }
307	    if (!hasSkip && delimiterCount + 1 != IPV6_PART_COUNT) {
308	      return null; // Incorrect number of parts
309	    }
310	
311	    ByteBuffer rawBytes = ByteBuffer.allocate(2 * IPV6_PART_COUNT);
312	    try {
313	      // Iterate through the parts of the ip string.
314	      // Invariant: start is always the beginning of a hextet, or the second ':' of the skip
315	      // sequence "::"
316	      int start = 0;
317	      if (ipString.charAt(0) == IPV6_DELIMITER) {
318	        start = 1;
319	      }
320	      while (start < ipString.length()) {
321	        int end = ipString.indexOf(IPV6_DELIMITER, start);
322	        if (end == -1) {
323	          end = ipString.length();
324	        }
325	        if (ipString.charAt(start) == IPV6_DELIMITER) {
326	          // expand zeroes
327	          for (int i = 0; i < partsSkipped; i++) {
328	            rawBytes.putShort((short) 0);
329	          }
330	
331	        } else {
332	          rawBytes.putShort(parseHextet(ipString, start, end));
333	        }
334	        start = end + 1;
335	      }
336	    } catch (NumberFormatException ex) {
337	      return null;
338	    }
339	    return rawBytes.array();
340	  }
