383	  private static int tryParseDecimal(String string, int start, int end) {
384	    int decimal = 0;
385	    int max = Integer.MAX_VALUE / 10; // for int overflow detection
386	    for (int i = start; i < end; i++) {
387	      if (decimal > max) {
388	        return -1;
389	      }
390	      decimal *= 10;
391	      int digit = Character.digit(string.charAt(i), 10);
392	      if (digit < 0) {
393	        return -1;
394	      }
395	      decimal += digit;
396	    }
397	    return decimal;
398	  }
